package com.bank.mail.service;

import com.bank.mail.model.Employee;
import java.util.List;
import java.util.logging.Logger;
import java.util.stream.Collectors;

public class MailingListService {
    private static final Logger log = Logger.getLogger(MailingListService.class.getName());

    public String recipientLine(List<Employee> employees) {
        log.info(() -> "Building recipient line from " + employees.size() + " employees");
        return employees.stream()
                .map(Employee::getEmail)
                .filter(email -> email != null)        // avoid NPE during join
                .collect(Collectors.joining(", "));    // comma + space delimiter
    }
}
