package com.bank.mail;

import com.bank.mail.model.Employee;
import com.bank.mail.service.MailingListService;
import java.util.Arrays;
import java.util.List;
import java.util.logging.Logger;

public class Main {
    private static final Logger log = Logger.getLogger(Main.class.getName());

    public static void main(String[] args) {
        List<Employee> staff = Arrays.asList(
            new Employee("Rajesh", "rajesh@nationalbank.co.in"),
            new Employee("Priya",  "priya@nationalbank.co.in"),
            new Employee("Amit",   null),                      // null email skipped
            new Employee("Neha",   "neha@nationalbank.co.in")
        );

        String recipients = new MailingListService().recipientLine(staff);
        log.info(() -> "To: " + recipients);
    }
}
